// Package aimark marks AI-generated output in a machine-readable, signed form
// and records it in a ledger, for EU AI Act Art 50(2) (GitHub #117; Art 50
// design §12.3 and §14.7).
//
// A mark is a signed statement that the content with this SHA-256 was
// generated by an AI system operated with Vornik. Every carrier (an email
// header, a hidden HTML comment, document metadata) carries the same compact
// form, base64url(payload) "." base64url(signature).
package aimark

import (
	"context"
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"sync/atomic"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promauto"
	"github.com/rs/zerolog"

	"vornik.io/vornik/internal/persistence"
)

// DigitalSourceType is the IPTC digital source type of AI-generated media.
const DigitalSourceType = "trainedAlgorithmicMedia"

// Mark is the signed payload. Fields are encoded in declaration order, and a
// third-party verifier reads exactly these bytes (§14.7 encoding): do not
// reorder them.
type Mark struct {
	V       int    `json:"v"`
	Gen     string `json:"gen"`
	Src     string `json:"src"`
	SHA256  string `json:"sha256"`
	Surface string `json:"surface"`
	IAT     string `json:"iat"`
	KID     string `json:"kid"`
}

// ForContent builds the unsigned mark for content emitted on surface.
func ForContent(content []byte, surface, release string, at time.Time) Mark {
	sum := sha256.Sum256(content)
	return forHash(hex.EncodeToString(sum[:]), surface, release, at)
}

func forHash(sha256hex, surface, release string, at time.Time) Mark {
	return Mark{
		V:       1,
		Gen:     "vornik/" + release,
		Src:     DigitalSourceType,
		SHA256:  sha256hex,
		Surface: surface,
		IAT:     at.UTC().Format(time.RFC3339),
	}
}

// validSHA256Hex reports whether h is a lowercase hex SHA-256.
func validSHA256Hex(h string) bool {
	if len(h) != 2*sha256.Size {
		return false
	}
	for _, c := range h {
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

// Keys maps a key id to its public key.
type Keys map[string]ed25519.PublicKey

// KID is a key's id: the first 8 bytes, hex, of SHA-256 of the public key.
func KID(pub ed25519.PublicKey) string {
	sum := sha256.Sum256(pub)
	return hex.EncodeToString(sum[:8])
}

// Signer signs marks with one Ed25519 key.
type Signer struct {
	priv ed25519.PrivateKey
	kid  string
}

// NewSigner returns a signer for the 32-byte seed.
func NewSigner(seed []byte) *Signer {
	priv := ed25519.NewKeyFromSeed(seed)
	return &Signer{priv: priv, kid: KID(priv.Public().(ed25519.PublicKey))}
}

// KID is the signer's key id.
func (s *Signer) KID() string { return s.kid }

// PublicKey is the signer's public key.
func (s *Signer) PublicKey() ed25519.PublicKey { return s.priv.Public().(ed25519.PublicKey) }

// Keys is the signer's own key, for verification.
func (s *Signer) Keys() Keys { return Keys{s.kid: s.PublicKey()} }

var b64 = base64.RawURLEncoding

// Sign stamps the signer's key id on m and returns the compact form and the
// mark as signed.
func (s *Signer) Sign(m Mark) (string, Mark, error) {
	m.KID = s.kid
	payload, err := json.Marshal(m)
	if err != nil {
		return "", Mark{}, err
	}
	sig := ed25519.Sign(s.priv, payload)
	return b64.EncodeToString(payload) + "." + b64.EncodeToString(sig), m, nil
}

// Verify checks a compact mark against the known keys and returns it. The
// signature is checked over the received payload bytes, never a re-encoding.
func Verify(compact string, keys Keys) (Mark, error) {
	p, s, ok := strings.Cut(compact, ".")
	if !ok {
		return Mark{}, errors.New("aimark: not a compact mark")
	}
	payload, err := b64.DecodeString(p)
	if err != nil {
		return Mark{}, fmt.Errorf("aimark: payload: %w", err)
	}
	sig, err := b64.DecodeString(s)
	if err != nil {
		return Mark{}, fmt.Errorf("aimark: signature: %w", err)
	}
	var m Mark
	if err := json.Unmarshal(payload, &m); err != nil {
		return Mark{}, fmt.Errorf("aimark: payload: %w", err)
	}
	pub, known := keys[m.KID]
	if !known {
		return Mark{}, fmt.Errorf("aimark: unknown key %q", m.KID)
	}
	if !ed25519.Verify(pub, payload, sig) {
		return Mark{}, errors.New("aimark: signature does not verify")
	}
	return m, nil
}

// Ledger records marks and the keys that signed them; the first write for
// a content hash (or a kid) wins. persistence.AIOutputMarkRepository
// implements it.
type Ledger interface {
	Record(ctx context.Context, m persistence.AIOutputMark) error
	RecordKey(ctx context.Context, k persistence.AIMarkKey) error
}

// RegisterKey records the signer's public key, so marks it signs stay
// verifiable after the key it was derived from is gone (§14.7, review 3701
// F2). Called at start-up; a repeat is a no-op.
func RegisterKey(ctx context.Context, l Ledger, s *Signer, now time.Time) error {
	return l.RecordKey(ctx, persistence.AIMarkKey{KID: s.KID(), PublicKey: s.PublicKey(), FirstUsedAt: now.UTC()})
}

// KeysFrom builds the verifier's key set from the persisted keys.
func KeysFrom(rows []persistence.AIMarkKey) Keys {
	keys := make(Keys, len(rows))
	for _, k := range rows {
		if len(k.PublicKey) == ed25519.PublicKeySize {
			keys[k.KID] = ed25519.PublicKey(k.PublicKey)
		}
	}
	return keys
}

// Marker signs and records the marks of one daemon.
type Marker struct {
	signer       *Signer
	ledger       Ledger
	release      func() string
	now          func() time.Time
	logger       zerolog.Logger
	ledgerErrors atomic.Int64
	errCounter   prometheus.Counter
}

// NewMarker returns a marker. release is read at each mark: the daemon learns
// its version after the marker is built. A nil logger logs nothing; a nil
// registerer registers no metric.
func NewMarker(signer *Signer, ledger Ledger, release func() string, logger *zerolog.Logger, reg prometheus.Registerer) *Marker {
	l := zerolog.Nop()
	if logger != nil {
		l = *logger
	}
	m := &Marker{signer: signer, ledger: ledger, release: release, now: time.Now, logger: l}
	if reg != nil {
		m.errCounter = promauto.With(reg).NewCounter(prometheus.CounterOpts{
			Namespace: "vornik",
			Name:      "aimark_ledger_errors_total",
			Help: "AI output marks (EU AI Act Art 50(2)) attached to sent output but NOT recorded in the " +
				"ai_output_marks ledger. Each is output that exact-copy detection will not find.",
		})
	}
	return m
}

// New marks content emitted on surface and records it. When the ledger
// write fails, the signed mark is still returned with the error: the caller
// attaches it and sends, the failure is counted and the mark is logged
// (§14.7, review 3701 F4).
func (m *Marker) New(ctx context.Context, content []byte, surface, taskID string) (string, Mark, error) {
	sum := sha256.Sum256(content)
	return m.NewForHash(ctx, hex.EncodeToString(sum[:]), surface, taskID)
}

// NewForHash is New for content whose SHA-256 (lowercase hex) is already
// known, such as a stored artifact's: the mark is the same as New's for
// those bytes, and the content is not read again.
func (m *Marker) NewForHash(ctx context.Context, sha256hex, surface, taskID string) (string, Mark, error) {
	if !validSHA256Hex(sha256hex) {
		return "", Mark{}, fmt.Errorf("aimark: %q is not a lowercase hex SHA-256", sha256hex)
	}
	compact, mark, err := m.signer.Sign(forHash(sha256hex, surface, m.release(), m.now()))
	if err != nil {
		return "", Mark{}, err
	}
	err = m.ledger.Record(ctx, persistence.AIOutputMark{
		ContentSHA256: mark.SHA256, Surface: surface, Mark: compact,
		TaskID: taskID, IssuedAt: m.now().UTC(),
	})
	if err != nil {
		m.ledgerErrors.Add(1)
		if m.errCounter != nil {
			m.errCounter.Inc()
		}
		m.logger.Warn().Err(err).Str("surface", surface).Str("ai_mark", compact).
			Msg("AI output mark not recorded in the ledger; the mark was still attached")
		return compact, mark, fmt.Errorf("aimark: ledger: %w", err)
	}
	return compact, mark, nil
}

// KID is the id of the key that signs this marker's marks.
func (m *Marker) KID() string { return m.signer.KID() }

// LedgerErrors is the number of marks not recorded since start.
func (m *Marker) LedgerErrors() int64 { return m.ledgerErrors.Load() }

// HiddenComment is the carrier for a body posted where Markdown renders (a
// GitHub issue, review or PR): a blank line and an HTML comment holding the
// compact mark. A verifier strips it and hashes the body above (Art 50
// design §14.8 C, commit 3).
func HiddenComment(compact string) string {
	return "\n\n<!-- vornik-ai-mark: " + compact + " -->"
}

// EncodeKey is a public key as published (base64url, no padding), the
// encoding the compact mark uses.
func EncodeKey(pub []byte) string { return b64.EncodeToString(pub) }
